seq = ''
with open('region.fasta') as f:
    for line in f:
        if line.startswith('>'):
            continue
        seq += line.strip()
n=len(seq)
comp={'A':'T','T':'A','G':'C','C':'G'}
def rc(s): return ''.join(comp[b] for b in reversed(s))

# all ORFs >= 150 bp
gencode_stops={'TAA','TAG','TGA'}
def find_orfs(s, strand):
    res=[]
    for frame in range(3):
        i=frame; start=None
        while i<len(s)-2:
            cod=s[i:i+3]
            if cod=='ATG' and start is None: start=i
            if cod in gencode_stops:
                if start is not None:
                    res.append((start,i+3,i+3-start,strand,frame))
                    start=None
            i+=3
    return res
orfs=find_orfs(seq,'+')+find_orfs(rc(seq),'-')
print("ORFs >= 150 bp:")
for o in sorted(orfs,key=lambda x:-x[2]):
    if o[2]>=150:
        print(f"  len {o[2]:5d} bp ({o[2]//3-1} aa) strand {o[3]} start {o[0]+1}-{o[1]}")

# direct repeats >= 12
print("\nRepeated 12-mers occurring >1:")
from collections import defaultdict
d=defaultdict(list)
for i in range(n-11):
    d[seq[i:i+12]].append(i)
reps={k:v for k,v in d.items() if len(v)>1}
for k,v in sorted(reps.items(), key=lambda x:-len(x[1]))[:10]:
    print(f"  {k}: positions {[p+1 for p in v]}")

# palindromes (inverted repeats) length >=10 with loop
print("\nInverted repeats (stem>=8):")
def palindromes(s, stem=8, maxloop=10):
    out=[]
    for i in range(len(s)-stem):
        for loop in range(0,maxloop+1):
            j=i+stem+loop
            if j+stem>len(s): break
            left=s[i:i+stem]
            right=s[j:j+stem]
            if left==rc(right):
                out.append((i+1,j+stem,loop,left))
    return out
pal=palindromes(seq,8,6)
for p in pal:
    print(f"  stem {p[3]} at {p[0]}..{p[1]} loop {p[2]}")
