def longorf(s):
    best=0
    for f in range(3):
        i=f;start=None
        while i<len(s)-2:
            c=s[i:i+3]
            if c=='ATG' and start is None:start=i
            if c in gencode_stops:
                if start is not None:
                    best=max(best,i+3-start);start=None
            i+=3
    return best
